fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    // Create a new vector with the same length as input
    let mut result = Vec::with_capacity(s.len());

    for &ch in s.iter() {
        // Check if ch is an uppercase ASCII letter 'A'..='Z'
        if ('A'..='Z').contains(&ch) {
            // Convert to lowercase by adding 32 to the code point
            // ASCII uppercase letters have codes 65..=90
            // Lowercase letters correspond to codes 97..=122 (65 + 32 = 97)
            let lowered = (ch as u8 + 32) as char;
            result.push(lowered);
        } else {
            // For other characters, just push as is
            result.push(ch);
        }
    }

    result
}